def ensure_link(original,target):
 original=pathlib.Path(original);target=pathlib.Path(target)
 if not original.is_file():raise FileNotFoundError(str(original))
 target.parent.mkdir(parents=True,exist_ok=True)
 if target.is_symlink():
  if target.resolve()!=original.resolve():raise RuntimeError("staging symlink points to a different source: "+str(target))
 elif target.exists():
  raise FileExistsError("expected a source symlink at "+str(target))
 else:
  target.symlink_to(original)

def validate_flux_header(path):
 data,header=torchsky.read(str(path),return_header=True)
 if data.ndim!=2 or not data.is_floating_point() or not bool(torch.isfinite(data).all()):
  raise ValueError("science product must be a finite floating 2D image: "+str(path))
 if data.dtype!=torch.float32:raise ValueError("science product must be float32 for the scorer: "+str(path))
 unit=str(header.get("BUNIT","")).lower().replace(" ","")
 if unit!="mjy/sr":raise ValueError("science product is missing MJy/sr BUNIT: "+str(path))
 return data,dict(header)

def validate_binary_support(path,require_float32):
 weight=torchsky.read(str(path))
 if weight.ndim!=2 or not bool(torch.isfinite(weight).all()) or bool((weight<0).any()):
  raise ValueError("support must be a finite nonnegative 2D array: "+str(path))
 values=torch.unique(weight)
 if not bool(((values==0)|(values==1)).all()):
  raise ValueError("support must be binary: "+str(path))
 if require_float32 and weight.dtype!=torch.float32:
  raise ValueError("reused control support is not float32: "+str(path))
 return weight

